IFL_DATA.register("diagrams", [{"id":"murabaha","title":"Murabaha (cost-plus sale)","topicId":"t9.3","conceptId":"murabaha","modeId":"murabaha","productIds":["consumer-murabaha","commodity-operations"],"summary":"The bank buys goods, owns them and bears their risk, then sells them to the client at disclosed cost plus an agreed profit, usually on deferred payment.","parties":[{"id":"client","label":"Client","x":12,"y":30},{"id":"bank","label":"Islamic bank","x":50,"y":30},{"id":"supplier","label":"Supplier","x":88,"y":30}],"steps":[{"from":"client","to":"bank","kind":"contract","label":"Requests goods","detail":"Client asks the bank to finance a specific lawful commodity."},{"from":"bank","to":"supplier","kind":"cash","label":"Bank pays cost","detail":"Bank buys the goods from a third-party supplier (not the client or its >50% affiliate)."},{"from":"supplier","to":"bank","kind":"goods","label":"Ownership & possession to bank","detail":"Bank acquires title and actual or constructive possession; goods are at the bank's risk."},{"from":"bank","to":"client","kind":"contract","label":"Murabaha sale: cost + profit","detail":"Bank discloses cost and sells at an agreed mark-up; one price fixed at contract."},{"from":"bank","to":"client","kind":"ownership","label":"Title and risk pass to client","detail":"Asset risk transfers to the client on execution of the sale."},{"from":"client","to":"bank","kind":"cash","label":"Deferred price paid","detail":"Price cannot be increased for delay; any late-payment penalty goes to charity."}],"rules":["Bank must own and bear risk before selling.","Mark-up runs from the date of sale, not disbursement.","No rollover, no buy-back (‘Inah)."],"pitfalls":["Selling goods the client already owns","Charging from disbursement date","Rolling over unpaid Murabaha"],"origin":["f1"]},{"id":"mpo","title":"Murabaha to Purchase Orderer (client as agent)","topicId":"t9.8.3","conceptId":"murabaha","modeId":"murabaha","productIds":["working-capital-murabaha"],"summary":"The client promises to buy, is appointed the bank's agent to purchase the goods, and then buys them from the bank by a separate offer and acceptance.","parties":[{"id":"client","label":"Client (promisor/agent)","x":15,"y":18},{"id":"bank","label":"Islamic bank","x":50,"y":45},{"id":"supplier","label":"Supplier","x":85,"y":18}],"steps":[{"from":"client","to":"bank","kind":"promise","label":"Master agreement & promise to buy","detail":"MoU/master Murabaha facility; client's unilateral binding promise; Hamish Jiddiyah may be taken."},{"from":"bank","to":"client","kind":"agency","label":"Agency agreement","detail":"Separate agency appointing the client to buy the goods on the bank's behalf — signed before purchase."},{"from":"client","to":"supplier","kind":"contract","label":"Agent buys for the bank","detail":"Client, as agent, purchases goods per specifications in the bank's name."},{"from":"bank","to":"supplier","kind":"cash","label":"Bank pays supplier directly","detail":"Direct payment reduces the risk of misuse of funds."},{"from":"supplier","to":"client","kind":"goods","label":"Delivery to agent (bank's risk)","detail":"Goods held by the agent are at the bank's risk until sale."},{"from":"client","to":"bank","kind":"contract","label":"Offer to buy / bank accepts","detail":"Murabaha concluded by separate offer and acceptance; goods must still exist."},{"from":"client","to":"bank","kind":"cash","label":"Deferred instalments","detail":"Fixed price paid as scheduled; no rollover, discount by stipulation or rebate by condition."}],"rules":["Agency must precede purchase.","Goods must exist (not consumed) at offer.","Invoice date not earlier than agency, not later than offer."],"pitfalls":["Client already bought goods before agency","Using goods in production before offer"],"origin":["f1"]},{"id":"salam","title":"Salam (forward sale, full prepayment)","topicId":"t10.10","conceptId":"salam","modeId":"salam","productIds":["salam-agri","livestock-finance"],"summary":"The bank pays the full price in advance for specified goods to be delivered later, then disposes of them by market sale, promise, agency or Parallel Salam.","parties":[{"id":"seller","label":"Producer (Salam seller)","x":15,"y":30},{"id":"bank","label":"Islamic bank (buyer)","x":50,"y":30},{"id":"buyer","label":"Final buyer","x":85,"y":30}],"steps":[{"from":"bank","to":"seller","kind":"contract","label":"Salam contract","detail":"Quantity, quality, delivery date and place fully specified."},{"from":"bank","to":"seller","kind":"cash","label":"Full price paid in advance","detail":"Salam capital must be paid at the contract session."},{"from":"buyer","to":"bank","kind":"promise","label":"Promise to buy (optional)","detail":"Third party promises to buy at an agreed price, possibly with Hamish Jiddiyah (Box 10.4)."},{"from":"seller","to":"bank","kind":"goods","label":"Delivery on due date","detail":"Bank takes delivery and bears the goods' risk."},{"from":"bank","to":"buyer","kind":"contract","label":"Bank sells the goods","detail":"Spot/credit sale, execution of promise, or sale through the seller as agent."}],"rules":["Only fungible, specifiable goods; not currencies or gold/silver against money.","Full prepayment.","Goods cannot be resold before possession (except via Parallel Salam)."],"pitfalls":["Deferring payment of the Salam price","Salam in an identified field's produce"],"origin":["f1"]},{"id":"parallel-salam","title":"Parallel Salam","topicId":"t10.6","conceptId":"salam","modeId":"salam","productIds":[],"summary":"The bank sells goods of the same description forward to a third party in a separate Salam, independent of its first Salam purchase.","parties":[{"id":"seller","label":"Producer","x":12,"y":30},{"id":"bank","label":"Islamic bank","x":50,"y":30},{"id":"buyer","label":"Third-party buyer","x":88,"y":30}],"steps":[{"from":"bank","to":"seller","kind":"contract","label":"Salam 1: bank buys","detail":"Bank pays the producer in advance for delivery on date D1."},{"from":"buyer","to":"bank","kind":"contract","label":"Salam 2: bank sells","detail":"Separate Salam: buyer prepays the bank for goods of the same description on date D2."},{"from":"buyer","to":"bank","kind":"cash","label":"Buyer prepays bank","detail":"Contracts are independent — Salam 2 cannot be conditional on Salam 1."},{"from":"seller","to":"bank","kind":"goods","label":"Producer delivers","detail":"If the producer fails, the bank must still deliver under Salam 2."},{"from":"bank","to":"buyer","kind":"goods","label":"Bank delivers","detail":"Bank's margin = Salam 2 price − Salam 1 price."}],"rules":["Second contract must be independent and enforceable on its own.","The bank remains liable to its buyer whatever happens to the first contract."],"pitfalls":["Making Salam 2 conditional on Salam 1"],"origin":["f1"]},{"id":"istisna","title":"Istisna‘a (order to manufacture)","topicId":"t10.11","conceptId":"istisna","modeId":"istisnaa","productIds":[],"summary":"A manufacturer undertakes to make an asset to specification for a fixed price that may be paid in advance, in instalments or on deferred terms.","parties":[{"id":"buyer","label":"Buyer (Mustasni‘)","x":20,"y":30},{"id":"maker","label":"Manufacturer (Sani‘)","x":80,"y":30}],"steps":[{"from":"buyer","to":"maker","kind":"contract","label":"Istisna‘a order","detail":"Specifications, price and delivery time fixed."},{"from":"buyer","to":"maker","kind":"cash","label":"Price: advance, instalments or deferred","detail":"Flexible payment — unlike Salam."},{"from":"maker","to":"maker","kind":"risk","label":"Manufacture with own materials","detail":"Manufacturer bears risk until delivery; Shart-e-Jazai may reduce price for delay."},{"from":"maker","to":"buyer","kind":"goods","label":"Delivery; ownership passes","detail":"Buyer may reject non-conforming goods."}],"rules":["Only for things that are manufactured or constructed.","Price and specifications fixed.","Revocable until work starts, binding thereafter (OIC, majority)."],"pitfalls":["Using Istisna‘a for natural produce (use Salam)"],"origin":["f1"]},{"id":"parallel-istisna","title":"Parallel Istisna‘a (bank as builder)","topicId":"t10.11.7","conceptId":"istisna","modeId":"istisnaa","productIds":["project-istisna","project-musharakah","istisna-sukuk"],"summary":"The bank contracts to deliver an asset to a customer and subcontracts manufacture to a contractor through an independent second Istisna‘a.","parties":[{"id":"customer","label":"Customer","x":12,"y":30},{"id":"bank","label":"Islamic bank","x":50,"y":30},{"id":"contractor","label":"Contractor","x":88,"y":30}],"steps":[{"from":"customer","to":"bank","kind":"contract","label":"Istisna‘a 1: bank will deliver","detail":"Bank sells the asset to the customer at a price, often deferred in instalments."},{"from":"bank","to":"contractor","kind":"contract","label":"Istisna‘a 2: bank orders","detail":"Independent contract with the contractor at a lower price, paid as work progresses."},{"from":"bank","to":"contractor","kind":"cash","label":"Progress payments","detail":"Bank finances construction."},{"from":"contractor","to":"bank","kind":"goods","label":"Asset delivered to bank","detail":"Bank bears risk until handing over."},{"from":"bank","to":"customer","kind":"goods","label":"Asset delivered to customer","detail":"Bank remains liable to customer for specifications."},{"from":"customer","to":"bank","kind":"cash","label":"Customer pays instalments","detail":"Bank's margin = customer price − contractor price."}],"rules":["Contracts independent.","Bank liable to customer even if contractor fails."],"pitfalls":["Linking the two contracts' obligations"],"origin":["f1"]},{"id":"ijarah","title":"Ijarah (operating lease)","topicId":"t11.3","conceptId":"ijarah","modeId":"ijarah","productIds":["corporate-ijarah","operating-lease"],"summary":"The bank owns an asset and leases its usufruct for rent; ownership risk and major costs stay with the bank.","parties":[{"id":"supplier","label":"Supplier","x":12,"y":30},{"id":"bank","label":"Islamic bank (lessor)","x":50,"y":30},{"id":"lessee","label":"Client (lessee)","x":88,"y":30}],"steps":[{"from":"bank","to":"supplier","kind":"cash","label":"Bank buys asset","detail":"Bank acquires ownership (possibly through the client as agent)."},{"from":"supplier","to":"bank","kind":"ownership","label":"Ownership with bank","detail":"Title in the bank's name or a counter deed."},{"from":"bank","to":"lessee","kind":"contract","label":"Ijarah contract","detail":"Asset, period and rent defined; first-period rent fixed, later benchmarked with cap/floor."},{"from":"bank","to":"lessee","kind":"goods","label":"Usable asset delivered","detail":"Rent accrues only from usable delivery."},{"from":"lessee","to":"bank","kind":"rent","label":"Periodic rent","detail":"Late rent: charity undertaking, not extra rent."},{"from":"bank","to":"bank","kind":"risk","label":"Lessor bears ownership risk","detail":"Major repairs, Takaful, loss without lessee fault; lessee bears usage costs."}],"rules":["Only non-consumable assets.","No rent before delivery.","On destruction without lessee fault, rent stops."],"pitfalls":["Charging remaining-period rent on early termination","Shifting all risk to the lessee"],"origin":["f1"]},{"id":"imbt","title":"Ijarah Muntahia-bi-Tamleek","topicId":"t11.5.1","conceptId":"imbt","modeId":"ijarah-muntahia-bi-tamleek","productIds":["auto-ijarah","farm-machinery-ijarah"],"summary":"An Ijarah combined with a separate unilateral promise to transfer ownership at the end by sale or gift.","parties":[{"id":"bank","label":"Islamic bank (lessor)","x":25,"y":30},{"id":"lessee","label":"Client (lessee)","x":75,"y":30}],"steps":[{"from":"lessee","to":"bank","kind":"promise","label":"Undertaking to lease + HJ","detail":"MoU and security deposit before the bank buys."},{"from":"bank","to":"lessee","kind":"contract","label":"Ijarah executed","detail":"Formal lease once the bank owns the usable asset."},{"from":"lessee","to":"bank","kind":"rent","label":"Rentals over the term","detail":"Rent can reflect cost; bank bears ownership risk and Takaful."},{"from":"bank","to":"lessee","kind":"promise","label":"Separate promise to sell/gift","detail":"Unilateral promise binding only on the promisor (AAOIFI methods: token price, remaining amount, market value, gift)."},{"from":"bank","to":"lessee","kind":"ownership","label":"Separate sale/gift deed","detail":"Ownership transfers by a separate contract at the end."}],"rules":["Lease and transfer kept separate.","Sale and lease-back only exceptionally, with a time gap (~1 year)."],"pitfalls":["Automatic transfer written into the lease","Rent continuing after theft/destruction"],"origin":["f1"]},{"id":"musharakah","title":"Musharakah","topicId":"t12.3.4","conceptId":"musharakah","modeId":"musharakah","productIds":["musharakah-trade","musharakah-export"],"summary":"Bank and client pool capital in a venture; profit is shared as agreed, loss strictly by capital contribution.","parties":[{"id":"bank","label":"Islamic bank (partner)","x":20,"y":15},{"id":"client","label":"Client (partner)","x":80,"y":15},{"id":"venture","label":"Joint venture","x":50,"y":48}],"steps":[{"from":"bank","to":"venture","kind":"cash","label":"Bank contributes capital","detail":"Capital commingled; appreciation belongs to all partners pro rata."},{"from":"client","to":"venture","kind":"cash","label":"Client contributes capital","detail":"Client usually manages; may get a larger profit share for work."},{"from":"venture","to":"venture","kind":"risk","label":"Business operates","detail":"Partners are mutual agents and trustees; no guarantee of capital or profit."},{"from":"venture","to":"bank","kind":"cash","label":"Profit by agreed ratio","detail":"Loss by capital ratio; drawings adjusted at final settlement."},{"from":"venture","to":"client","kind":"cash","label":"Profit by agreed ratio","detail":"A declared sleeping partner cannot exceed his capital ratio (Hanafi view)."}],"rules":["Profit as agreed, loss by capital.","No lump-sum or %-of-capital profit.","Security only against negligence."],"pitfalls":["Guaranteeing the bank's capital","Buy-out at face value"],"origin":["f1"]},{"id":"mudarabah","title":"Mudarabah","topicId":"t12.4","conceptId":"mudarabah","modeId":"mudarabah","productIds":[],"summary":"The Rabbul-mal provides capital, the Mudarib manages; profit shared as agreed, financial loss borne by the capital owner.","parties":[{"id":"rabb","label":"Rabbul-mal (investor)","x":18,"y":30},{"id":"mudarib","label":"Mudarib (manager)","x":55,"y":30},{"id":"business","label":"Business","x":88,"y":30}],"steps":[{"from":"rabb","to":"mudarib","kind":"cash","label":"Capital provided","detail":"Money or assets valued in money — not a debt owed by the Mudarib."},{"from":"mudarib","to":"business","kind":"agency","label":"Mudarib manages","detail":"Restricted or unrestricted; Mudarib is a trustee liable only for negligence/breach."},{"from":"business","to":"mudarib","kind":"cash","label":"Profit realised","detail":"Profit exists only after capital is kept intact."},{"from":"mudarib","to":"rabb","kind":"cash","label":"Capital + agreed profit share","detail":"Loss (erosion of capital) is borne by the Rabbul-mal; the Mudarib loses his effort."}],"rules":["No salary for the Mudarib beyond his share.","Void Mudarabah → Ujratul-mithl only."],"pitfalls":["Converting a debt into Mudarabah capital","Guaranteeing the investor's capital"],"origin":["f1"]},{"id":"dm","title":"Diminishing Musharakah (housing)","topicId":"t12.9.2","conceptId":"diminishing-musharakah","modeId":"diminishing-musharakah","productIds":["home-dm","farm-structures-dm"],"summary":"Bank and client co-own a house; the client rents the bank's share and buys its units over time, so rent falls.","parties":[{"id":"bank","label":"Islamic bank","x":20,"y":30},{"id":"house","label":"House (joint ownership)","x":50,"y":50},{"id":"client","label":"Client","x":80,"y":30}],"steps":[{"from":"bank","to":"house","kind":"cash","label":"Bank funds its share (e.g. 80%)","detail":"Musharakah agreement creating joint ownership (Shirkatulmilk)."},{"from":"client","to":"house","kind":"cash","label":"Client funds its share (e.g. 20%)","detail":"Both parties bear ownership costs pro rata."},{"from":"bank","to":"client","kind":"contract","label":"Lease of bank's share","detail":"Rent agreement under Ijarah rules."},{"from":"client","to":"bank","kind":"promise","label":"Undertaking to buy units","detail":"Unilateral promise; pre-agreed price schedule allowed in Shirkatulmilk."},{"from":"client","to":"bank","kind":"rent","label":"Monthly: rent + one unit","detail":"Box 12.5: 6,666.67 unit + rent on outstanding units (4,666.67 in month 1)."},{"from":"bank","to":"client","kind":"ownership","label":"Title transfers after last unit","detail":"Each unit sold by separate offer and acceptance."}],"rules":["Three separate, independently enforceable contracts.","In Shirkatul‘aqd DM, units at market value only."],"pitfalls":["Making the contracts conditional on each other","Renting a non-leasable asset (open plot)"],"origin":["f1"]},{"id":"sukuk","title":"Ijarah Sukuk (sale and lease-back)","topicId":"t15.3.5.b","conceptId":"sukuk","modeId":"sukuk","productIds":["ijarah-sukuk","ijarah-fund"],"summary":"An SPV buys an asset from the originator, issues certificates to investors, leases the asset back and passes rent to holders; the originator repurchases at maturity.","parties":[{"id":"originator","label":"Originator / government","x":12,"y":30},{"id":"spv","label":"SPV (issuer/trustee)","x":50,"y":30},{"id":"investors","label":"Sukuk holders","x":88,"y":30}],"steps":[{"from":"investors","to":"spv","kind":"cash","label":"Subscription proceeds","detail":"Investors buy certificates of undivided ownership."},{"from":"spv","to":"originator","kind":"cash","label":"SPV buys asset (true sale)","detail":"E.g. M-2 motorway land in Pakistan's 2005 Sukuk."},{"from":"originator","to":"spv","kind":"ownership","label":"Ownership to SPV","detail":"Segregated, bankruptcy-remote."},{"from":"spv","to":"originator","kind":"contract","label":"Lease back","detail":"Rent benchmarked (e.g. 6-month LIBOR + 220 bps)."},{"from":"originator","to":"spv","kind":"rent","label":"Periodic rent","detail":"Holders bear ownership risk; returns quasi-fixed."},{"from":"spv","to":"investors","kind":"cash","label":"Distributions","detail":"Tradable at market price because they represent assets."},{"from":"originator","to":"spv","kind":"cash","label":"Repurchase at maturity","detail":"Under a separate undertaking; proceeds redeem the Sukuk."}],"rules":["Sukuk must represent real ownership, not only rent.","Issuer may not guarantee capital or fixed profit."],"pitfalls":["‘Inah-based structures","Discounted trading of debt Sukuk"],"origin":["f1"]},{"id":"takaful","title":"Takaful (Wakalah–Waqf model)","topicId":"t16.4.1","conceptId":"takaful","modeId":"takaful","productIds":["takaful"],"summary":"Participants donate to a Waqf fund managed by an operator for a fee; claims are paid from the fund and surplus belongs to participants.","parties":[{"id":"participants","label":"Participants","x":15,"y":30},{"id":"fund","label":"Waqf / Takaful fund","x":50,"y":30},{"id":"operator","label":"Takaful operator","x":85,"y":30}],"steps":[{"from":"operator","to":"fund","kind":"cash","label":"Shareholders' initial Waqf donation","detail":"Creates the Waqf fund."},{"from":"participants","to":"fund","kind":"cash","label":"Contributions (Tabarru‘)","detail":"Donation to the fund for mutual help."},{"from":"fund","to":"operator","kind":"cash","label":"Wakalah fee (25–30%)","detail":"Operator bears management expenses from its fee (Box 16.1 example)."},{"from":"operator","to":"fund","kind":"agency","label":"Invests fund (Mudarabah 40:60)","detail":"Operator shares investment profit as Mudarib."},{"from":"fund","to":"participants","kind":"cash","label":"Claims paid","detail":"Losses of the few covered by the many."},{"from":"fund","to":"participants","kind":"cash","label":"Underwriting surplus","detail":"Belongs to participants; deficits covered by Qard al Hasan from shareholders."}],"rules":["Operator should not take UWS as a risk-taker.","Only Shari’ah-compliant investments."],"pitfalls":["Operator sharing surplus but not deficit"],"origin":["f1"]},{"id":"tawarruq","title":"Tawarruq (acceptable form)","topicId":"t13.3","conceptId":"tawarruq","modeId":"tawarruq","productIds":["liquidity-tools","personal-tawarruq"],"summary":"A person needing cash buys a commodity from the bank on credit, takes possession and sells it to an unrelated third party for spot cash. Selling it back to the bank would be ‘Inah.","parties":[{"id":"market","label":"Commodity market","x":12,"y":10},{"id":"bank","label":"Islamic bank","x":60,"y":10},{"id":"client","label":"Mutawarriq (client)","x":30,"y":52},{"id":"buyer","label":"Unrelated third-party buyer","x":85,"y":52}],"steps":[{"from":"bank","to":"market","kind":"cash","label":"Bank buys commodity for cash","detail":"A liquid commodity with a brisk market; the bank takes ownership and risk (pp. 350–351)."},{"from":"market","to":"bank","kind":"goods","label":"Ownership and possession to bank","detail":"The bank must not appoint the client as agent to buy and then sell to himself (p. 350)."},{"from":"bank","to":"client","kind":"contract","label":"Credit sale (Murabaha)","detail":"A separate contract with proper offer and acceptance."},{"from":"bank","to":"client","kind":"ownership","label":"Client takes delivery","detail":"Asset risk passes to the client."},{"from":"client","to":"buyer","kind":"goods","label":"Spot sale to a third party","detail":"Not to the original seller, directly or through an agent (AAOIFI)."},{"from":"buyer","to":"client","kind":"cash","label":"Cash to client","detail":"The client gets liquidity."},{"from":"client","to":"bank","kind":"cash","label":"Deferred price paid","detail":"Fixed price; no increase for delay."}],"rules":["Sale back to the bank is ‘Inah, which is invalid.","An agency to sell, stipulated in the sale, is invalid; if made after an unconditional sale it is valid but not advisable.","Limit to unavoidable liquidity needs, under Shari’ah-board supervision (p. 351)."],"pitfalls":["Paper-only commodity trades where goods never move","Using Tawarruq for consumer finance at scale"],"origin":["f1"]},{"id":"jualah","title":"Ju‘alah with Parallel Ju‘alah (Figure 13.1)","topicId":"t13.4.5","conceptId":"jualah","modeId":"juaalah","productIds":["jualah-services"],"summary":"The bank undertakes uncertain work for a customer for an agreed reward, and has it done by a specialist under a separate, independent Parallel Ju‘alah.","parties":[{"id":"customer","label":"Customer (offeror)","x":12,"y":30},{"id":"bank","label":"Islamic bank","x":50,"y":30},{"id":"worker","label":"Specialist worker","x":88,"y":30}],"steps":[{"from":"customer","to":"bank","kind":"contract","label":"1 · Negotiates uncertain work, time, reward","detail":"E.g. recovery of a debt or a lost asset (p. 353)."},{"from":"bank","to":"customer","kind":"contract","label":"2 · Ju‘alah contract","detail":"After a cost–benefit analysis."},{"from":"bank","to":"worker","kind":"contract","label":"3 · Parallel Ju‘alah","detail":"Allowed only if the first contract does not require the bank to do the work itself."},{"from":"bank","to":"worker","kind":"cash","label":"4 · Reward paid on completion","detail":"No result, no reward; revocation after work starts means a market wage."},{"from":"customer","to":"bank","kind":"cash","label":"5 · Bank collects its reward","detail":"The bank’s margin is the difference between the two rewards."}],"rules":["Reward known and deliverable; it may be a share of the result.","The two contracts are independent.","The task must not already be the worker’s legal duty."],"pitfalls":["Paying the full reward before the result as if earned","Making one contract conditional on the other"],"origin":["f1"]},{"id":"securitisation","title":"Securitisation through an SPV (Figure 15.1)","topicId":"t15.3.1","conceptId":"sukuk","modeId":"sukuk","productIds":["musharakah-sukuk"],"summary":"The originator sells assets to a bankruptcy-remote SPV, which funds the purchase by issuing Sukuk. Holders own the assets pro rata and receive the cash flows they generate.","parties":[{"id":"originator","label":"Originator","x":12,"y":15},{"id":"spv","label":"SPV (trustee/issuer)","x":50,"y":15},{"id":"investors","label":"Sukuk holders","x":88,"y":15},{"id":"obligors","label":"Obligors / lessees","x":50,"y":50}],"steps":[{"from":"originator","to":"spv","kind":"ownership","label":"True sale of assets","detail":"Proper segregation; irreversible even on the originator’s insolvency (p. 395)."},{"from":"spv","to":"investors","kind":"contract","label":"Issues Sukuk","detail":"Certificates of undivided ownership in the assets."},{"from":"investors","to":"spv","kind":"cash","label":"Subscription proceeds","detail":"Used to pay the purchase price."},{"from":"spv","to":"originator","kind":"cash","label":"Purchase price","detail":"The originator turns illiquid assets into cash (accumulator becomes distributor)."},{"from":"obligors","to":"spv","kind":"rent","label":"Rentals / collections","detail":"Collected by a servicer and paid to the SPV."},{"from":"spv","to":"investors","kind":"cash","label":"Pass-through or pay-through distributions","detail":"Returns come from the assets’ cash flows."}],"rules":["Ownership must pass to holders; rent receivables alone are debt.","Pools of receivables trade only under Hawalah rules unless tangible assets exceed the threshold.","No issuer guarantee of capital or fixed profit (AAOIFI)."],"pitfalls":["Securitising credit-card receivables as tradable paper","Guaranteed fixed returns"],"origin":["f1"]},{"id":"deposit-pool","title":"Two-tier Mudarabah deposit pool","topicId":"t12.7.1","conceptId":"mudarabah","modeId":"mudarabah","productIds":["mudarabah-deposit"],"summary":"Depositors are Rabbul-mal and the bank is Mudarib. Pooled funds are invested with fund users; net pool income is shared by the agreed ratio and then among depositors by weightages and daily products.","parties":[{"id":"depositors","label":"Depositors (Rabbul-mal)","x":12,"y":30},{"id":"bank","label":"Bank (Mudarib)","x":50,"y":30},{"id":"users","label":"Fund users (Murabaha, Ijarah, Musharakah…)","x":88,"y":30}],"steps":[{"from":"depositors","to":"bank","kind":"cash","label":"Deposits pooled","detail":"Weightages by tenor and disclosed; changed only at the start of a period (p. 331)."},{"from":"bank","to":"users","kind":"cash","label":"Funds invested","detail":"Through trade, lease and partnership modes."},{"from":"users","to":"bank","kind":"cash","label":"Returns to the pool","detail":"Direct expenses charged to the pool; head-office costs borne by the bank."},{"from":"bank","to":"depositors","kind":"contract","label":"Profit shared: pool vs Mudarib","detail":"By the agreed ratio after constructive liquidation."},{"from":"bank","to":"depositors","kind":"cash","label":"Pool share distributed","detail":"By daily products and weightages. A loss is borne by the pool by investment ratio, and the bank then earns nothing."}],"rules":["No fixed return may be promised.","Bank equity: Musharakah if added at the pool’s creation, Mudarabah if added later.","Donations from the bank’s own profit are allowed if not pre-agreed."],"pitfalls":["Charging head-office costs to the pool","Secret profit smoothing without disclosure"],"origin":["f1"]},{"id":"salam-murabaha","title":"Salam + Murabaha for cotton (Box 14.2)","topicId":"t14.3.2","conceptId":"salam","modeId":"salam","productIds":[],"summary":"The bank buys cotton from growers by Salam, takes a textile mill’s promise to buy, appoints the mill its agent to take delivery, and then sells the cotton to the mill by Murabaha.","parties":[{"id":"grower","label":"Cotton grower","x":12,"y":30},{"id":"bank","label":"Islamic bank","x":50,"y":30},{"id":"mill","label":"Textile mill","x":88,"y":30}],"steps":[{"from":"bank","to":"grower","kind":"cash","label":"Salam price paid in full","detail":"The grower gets cash for future produce."},{"from":"mill","to":"bank","kind":"promise","label":"Promise to buy at an agreed price","detail":"Hedges the mill against price rises."},{"from":"grower","to":"mill","kind":"goods","label":"Delivery to the mill as the bank’s agent","detail":"The mill takes delivery on the bank’s behalf; the goods are at the bank’s risk."},{"from":"bank","to":"mill","kind":"contract","label":"Murabaha sale","detail":"Offer and acceptance after the mill reports possession."},{"from":"mill","to":"bank","kind":"cash","label":"Deferred Murabaha price","detail":"The bank avoids holding inventory."}],"rules":["The two contracts are separate.","Salam goods cannot be sold before possession; hence the promise and the later Murabaha."],"pitfalls":["Selling to the mill before the bank takes (constructive) delivery"],"origin":["f1"]},{"id":"salam-sugar","title":"Salam with agency for working capital (sugar mill)","topicId":"t14.4.1","conceptId":"salam","modeId":"salam","productIds":["salam-working-capital"],"summary":"The bank prepays a sugar mill under Salam. At delivery it takes possession and appoints the mill its agent to sell the sugar at an agreed price; the bank bears the price risk.","parties":[{"id":"bank","label":"Islamic bank","x":15,"y":30},{"id":"mill","label":"Sugar mill (seller and agent)","x":50,"y":30},{"id":"market","label":"Market buyers","x":85,"y":30}],"steps":[{"from":"bank","to":"mill","kind":"cash","label":"Full Salam price in advance","detail":"The bank may take a charge on the mill’s assets (p. 370)."},{"from":"bank","to":"mill","kind":"agency","label":"Agency agreement to sell","detail":"At an agreed price; an excess may be kept by the mill as a bonus if agreed."},{"from":"mill","to":"bank","kind":"goods","label":"Delivery from the godowns","detail":"The bank takes delivery before authorising the sale."},{"from":"mill","to":"market","kind":"goods","label":"Mill sells as agent","detail":"On the bank’s behalf."},{"from":"mill","to":"bank","kind":"cash","label":"Sale proceeds to bank","detail":"If the market price falls below the agreed price, the bank bears the loss."}],"rules":["Salam capital paid in full at contract.","The bank must take delivery before the agent sells."],"pitfalls":["Guaranteeing the bank’s return through the mill"],"origin":["f1"]},{"id":"iers","title":"SBP Islamic Export Refinance Scheme","topicId":"t14.4.6","conceptId":"musharakah","modeId":"musharakah","productIds":["iers"],"summary":"The State Bank shares in the actual profit of an Islamic bank’s Musharakah pool of export financings. Profit above the conventional EFS rate goes to a Takaful fund held by SBP.","parties":[{"id":"sbp","label":"State Bank of Pakistan","x":12,"y":10},{"id":"bank","label":"Islamic bank’s Musharakah pool","x":50,"y":42},{"id":"exporters","label":"Blue-chip exporters (≥10)","x":88,"y":10},{"id":"fund","label":"Takaful fund at SBP","x":12,"y":55}],"steps":[{"from":"sbp","to":"bank","kind":"cash","label":"Refinance into the pool","detail":"Only against underlying transactions approved by the bank’s Shari’ah board."},{"from":"bank","to":"exporters","kind":"cash","label":"Export finance by Islamic modes","detail":"Pool of at least ten blue-chip companies."},{"from":"exporters","to":"bank","kind":"cash","label":"Pool income","detail":"Shared on a daily-product basis."},{"from":"bank","to":"sbp","kind":"cash","label":"SBP’s profit share (quarterly, provisional)","detail":"Settled against audited accounts."},{"from":"bank","to":"fund","kind":"cash","label":"Excess profit to Takaful fund","detail":"Within seven days of determination."},{"from":"fund","to":"sbp","kind":"risk","label":"Absorbs SBP’s loss share first","detail":"Losses are shared by investment ratio."}],"rules":["Profit and loss are actual, not fixed.","SBP’s loss share is met first from the Takaful fund."],"pitfalls":["Treating refinance as a fixed-rate loan"],"origin":["f1"]},{"id":"running-musharakah","title":"Running Musharakah (working capital)","topicId":"t12.7.2","conceptId":"musharakah","modeId":"musharakah","productIds":["running-musharakah"],"summary":"The bank provides a Musharakah limit for the client’s running business. Sale proceeds of finished goods flow through a Running Musharakah Account, and each month or quarter the bank takes its agreed share of the computed operating profit.","parties":[{"id":"bank","label":"Islamic bank","x":15,"y":30},{"id":"account","label":"Running Musharakah Account","x":50,"y":30},{"id":"client","label":"Client’s business","x":85,"y":30}],"steps":[{"from":"bank","to":"account","kind":"contract","label":"Musharakah limit approved","detail":"Clients are grouped as seasonal, cyclical or continuous for the period of the limit (p. 333)."},{"from":"account","to":"client","kind":"cash","label":"Client draws as needed","detail":"The bank’s capital is measured by the average amount utilised (daily product) (p. 314)."},{"from":"client","to":"account","kind":"cash","label":"Sale proceeds credited","detail":"Only proceeds from selling finished goods — not sales of fixed assets or long-term loans."},{"from":"account","to":"bank","kind":"cash","label":"Periodic profit share","detail":"Based on the computed operating profit for the period, at the agreed ratio."},{"from":"client","to":"bank","kind":"risk","label":"Loss shared by capital","detail":"Security covers only negligence, misconduct or breach."}],"rules":["Profit is a ratio of actual operating profit, never a fixed amount.","Loss follows the capital ratio."],"pitfalls":["Crediting non-operating cash flows to inflate the base","Guaranteeing the bank’s profit"],"origin":["f1"]},{"id":"musawamah-export","title":"Musawamah alternative to bill discounting (Section 14.4.2)","topicId":"t14.4.2","conceptId":"musawamah","modeId":"musawamah","productIds":["export-bill-musawamah"],"summary":"Instead of discounting an export bill, the bank advances local currency to the exporter as its agent to buy goods, then sells him those goods for the bill’s foreign-currency amount, payable on the bill date.","parties":[{"id":"bank","label":"Islamic bank","x":15,"y":30},{"id":"exporter","label":"Exporter (client/agent)","x":50,"y":30},{"id":"foreign","label":"Foreign buyer’s bank","x":85,"y":30}],"steps":[{"from":"exporter","to":"bank","kind":"contract","label":"Bill US$100,000 due in 55 days","detail":"Spot Rs.57.75; the bank quotes Rs.57.60 (p. 371)."},{"from":"bank","to":"exporter","kind":"cash","label":"Rs.5,760,000 as agent to buy goods","detail":"Under an agency agreement, for the raw materials the exporter needs."},{"from":"exporter","to":"bank","kind":"goods","label":"Declaration of possession","detail":"The exporter buys the goods for the bank and declares possession."},{"from":"exporter","to":"bank","kind":"contract","label":"Offer to buy for US$100,000","detail":"Payable on 25 February; the bank accepts — a Musawamah sale."},{"from":"foreign","to":"exporter","kind":"cash","label":"Bill proceeds received","detail":"Remitted into the exporter’s account at the Islamic bank."},{"from":"exporter","to":"bank","kind":"cash","label":"US$100,000 debited","detail":"Settles the Musawamah price."}],"rules":["The bank must own the goods before selling them.","No discounting of the bill itself."],"pitfalls":["Paying cash without any goods changing hands"],"origin":["f1"]},{"id":"import-murabaha","title":"Import L/C Murabaha with sub-Murabaha (Section 14.4.2)","topicId":"t14.4.2","conceptId":"murabaha","modeId":"murabaha","productIds":["import-murabaha","shipping-guarantee-murabaha"],"summary":"The bank opens an L/C to import goods for itself through the client as agent. When documents arrive it sells the goods to the client, for cash (Musawamah at L/C cost plus charges) or on credit (sub-Murabaha).","parties":[{"id":"client","label":"Importer (agent/buyer)","x":12,"y":30},{"id":"bank","label":"Islamic bank","x":50,"y":30},{"id":"exporter","label":"Foreign exporter","x":88,"y":30}],"steps":[{"from":"client","to":"bank","kind":"agency","label":"Master Murabaha + agency agreement","detail":"Signed before the L/C is opened (p. 372)."},{"from":"bank","to":"exporter","kind":"contract","label":"L/C opened","detail":"At the client’s request, with the relevant documents."},{"from":"exporter","to":"bank","kind":"goods","label":"Goods shipped; documents to bank","detail":"The goods are at the bank’s risk."},{"from":"bank","to":"exporter","kind":"cash","label":"Nostro debited — bill paid","detail":"Profit on credit runs from this date."},{"from":"bank","to":"client","kind":"contract","label":"Sub-Murabaha or Musawamah","detail":"Credit: client offers, bank accepts; price fixed. Cash: L/C cost plus charges."},{"from":"client","to":"bank","kind":"cash","label":"Payment on settlement date","detail":"If a shipping guarantee was used, only the cost part can be adjusted later."}],"rules":["The agency must precede the purchase.","Profit runs from the Nostro debit to the settlement date."],"pitfalls":["Adjusting the profit part after the sale"],"origin":["f1"]},{"id":"mudarabah-sukuk","title":"Mudarabah Sukuk (OIC Fiqh Council 1988)","topicId":"t15.3.5","conceptId":"mudarabah","modeId":"mudarabah","productIds":["mudarabah-sukuk"],"summary":"The issuer, as Mudarib, raises capital from subscribers through Mudarabah certificates and invests it in a project. Profit is shared by the prospectus ratio, and loss falls on the certificate holders.","parties":[{"id":"holders","label":"Certificate holders (Rabbul-mal)","x":12,"y":30},{"id":"issuer","label":"Issuer / SPV (Mudarib)","x":50,"y":30},{"id":"project","label":"Project","x":88,"y":30}],"steps":[{"from":"issuer","to":"holders","kind":"contract","label":"Prospectus: capital, ratio, conditions","detail":"No guarantee of capital or of a fixed profit by the issuer (p. 399)."},{"from":"holders","to":"issuer","kind":"cash","label":"Subscription = Mudarabah capital","detail":"The Mudarib may add its own funds and earn on them too."},{"from":"issuer","to":"project","kind":"cash","label":"Capital deployed","detail":"Trading rules change as cash becomes assets."},{"from":"project","to":"issuer","kind":"cash","label":"Project income","detail":"The P&L account must be published to holders."},{"from":"issuer","to":"holders","kind":"cash","label":"Profit by agreed ratio","detail":"Reserves may be created; an unrelated third party may promise to cover losses free of charge."},{"from":"project","to":"holders","kind":"risk","label":"Loss borne by holders","detail":"The Mudarib loses its effort only, unless negligent."}],"rules":["Cash stage: Sarf rules; debt stage: debt rules; mixed assets: market price.","No issuer guarantee."],"pitfalls":["Promising a fixed percentage of capital"],"origin":["f1"]},{"id":"hawalah","title":"Hawalah (assignment of debt)","topicId":"t7.14","conceptId":"hawalah","modeId":"hawalah","productIds":[],"summary":"A debtor transfers his debt to a third party, who becomes responsible for paying the creditor; the original debtor is freed. It is gratuitous and at face value.","parties":[{"id":"creditor","label":"Creditor","x":12,"y":30},{"id":"debtor","label":"Original debtor (assignor)","x":50,"y":30},{"id":"assignee","label":"Assignee (new payer)","x":88,"y":30}],"steps":[{"from":"creditor","to":"debtor","kind":"cash","label":"Original debt exists","detail":"E.g. the debtor owes 100,000."},{"from":"debtor","to":"assignee","kind":"contract","label":"Assignment agreed","detail":"Restricted (paid from the assignor’s property held by the assignee) or unrestricted (p. 167)."},{"from":"assignee","to":"creditor","kind":"promise","label":"Assignee accepts liability","detail":"Takes effect immediately; payment may still be at the due date."},{"from":"assignee","to":"creditor","kind":"cash","label":"Payment at face value","detail":"No remuneration for the Hawalah itself; no discount."},{"from":"creditor","to":"debtor","kind":"risk","label":"Recourse if the assignee fails","detail":"On the majority view, the debt returns to the assignor if the assignee dies or becomes bankrupt."}],"rules":["Face value only.","Gratuitous: no fee for the assignment itself."],"pitfalls":["Using it to sell debts at a discount"],"origin":["f1"]},{"id":"istisna-housing","title":"Housing finance through Istisna‘a and Diminishing Musharakah (Box 10.13)","topicId":"t10.11.10","conceptId":"istisna","modeId":"istisnaa","productIds":["apartment-istisna-dm"],"summary":"Client and bank jointly buy a flat under construction from a builder by Istisna‘a; after handover the bank leases its share to the client, who buys it unit by unit.","parties":[{"id":"client","label":"Client A (Rs.2 m)","x":14,"y":30},{"id":"bank","label":"Bank B (Rs.5 m)","x":50,"y":8},{"id":"builder","label":"Builder C","x":86,"y":30}],"steps":[{"from":"client","to":"bank","kind":"contract","label":"Shirkatulmilk pool of Rs.7 m","detail":"A contributes Rs.2 m and B Rs.5 m for a flat priced Rs.7 m (p. 275)."},{"from":"bank","to":"builder","kind":"contract","label":"Joint Istisna‘a with the builder","detail":"A and B jointly contract for a flat of defined specifications."},{"from":"bank","to":"builder","kind":"cash","label":"Rs.7 m in four instalments","detail":"The price is paid as construction proceeds."},{"from":"bank","to":"client","kind":"agency","label":"Client supervises construction","detail":"The bank appoints A its agent to supervise the work."},{"from":"builder","to":"client","kind":"goods","label":"Flat handed over","detail":"Ownership is joint in the ratio 2 : 5."},{"from":"bank","to":"client","kind":"rent","label":"Bank leases its share","detail":"Rent is charged on the bank’s share only."},{"from":"client","to":"bank","kind":"cash","label":"Monthly unit purchases","detail":"Rent falls after each unit; after ten years ownership passes to A (Diminishing Musharakah)."}],"rules":["The builder deals in cash and has no financing relationship with the bank.","Rent starts only after handover; before that the bank is a co-owner of a flat under construction."],"pitfalls":["Charging rent during construction","Treating the bank’s share as a loan"],"origin":["f1"]},{"id":"istisna-export","title":"Istisna‘a for pre-shipment export finance (Box 10.14)","topicId":"t10.11.10","conceptId":"istisna","modeId":"istisnaa","productIds":["export-istisna"],"summary":"The bank buys the export goods from the exporter by Istisna‘a, takes delivery and bears their risk, then exports them through the exporter as its agent.","parties":[{"id":"exporter","label":"Exporter A","x":14,"y":30},{"id":"bank","label":"Bank B","x":50,"y":8},{"id":"importer","label":"Foreign importer","x":86,"y":30}],"steps":[{"from":"bank","to":"exporter","kind":"contract","label":"Istisna‘a for Rs.100 m","detail":"Garments of a specified nature to be supplied within three months (p. 276)."},{"from":"bank","to":"exporter","kind":"agency","label":"Exporter appointed export agent","detail":"Effective once the garments are the bank’s."},{"from":"importer","to":"bank","kind":"contract","label":"L/C of Rs.110 m","detail":"Opened in the bank’s name. If an L/C already exists, Istisna‘a is not possible (it would be ‘Inah)."},{"from":"exporter","to":"bank","kind":"goods","label":"Bank takes delivery","detail":"Actual or constructive possession; the garments are now at the bank’s risk."},{"from":"exporter","to":"importer","kind":"goods","label":"Goods exported as the bank’s agent","detail":"Documents are sent on the bank’s behalf."},{"from":"importer","to":"bank","kind":"cash","label":"Rs.110 m under the L/C","detail":"The bank’s gross margin of Rs.10 m is earned by owning and exporting goods."}],"rules":["No existing L/C for the same sale when the Istisna‘a is signed.","The bank must take delivery and bear the goods’ risk before export."],"pitfalls":["Buying from the exporter after the L/C is opened","Skipping the bank’s possession"],"origin":["f1"]},{"id":"ijarah-istisna-project","title":"Syndicated Ijarah–Istisna‘a for an oil terminal (p. 374)","topicId":"t14.4.3","conceptId":"istisna","modeId":"istisnaa","productIds":["syndication"],"summary":"A consortium commissions the terminal by Istisna‘a, with the operator supervising as its agent, and leases the completed terminal to the operator under a prior binding promise.","parties":[{"id":"operator","label":"Terminal operator","x":14,"y":30},{"id":"syndicate","label":"Bank consortium","x":50,"y":8},{"id":"contractor","label":"Contractor","x":86,"y":30}],"steps":[{"from":"operator","to":"syndicate","kind":"promise","label":"Binding promise to lease","detail":"A unilateral promise gives the consortium comfort before it commits funds."},{"from":"syndicate","to":"contractor","kind":"contract","label":"Istisna‘a to build the terminal","detail":"Price paid in stages as the work proceeds."},{"from":"syndicate","to":"operator","kind":"agency","label":"Operator supervises construction","detail":"As the consortium’s agent."},{"from":"contractor","to":"syndicate","kind":"goods","label":"Completed terminal delivered","detail":"The consortium owns it and bears ownership risk."},{"from":"syndicate","to":"operator","kind":"rent","label":"Ijarah executed","detail":"Rent runs only once the terminal is ready for use."}],"rules":["Ijarah cannot start until the asset exists and can be used.","The consortium members own the terminal in proportion to their funding."],"pitfalls":["Charging rent during construction","Signing the Ijarah before the asset exists"],"origin":["f1"]},{"id":"interbank-mii","title":"Mudarabah interbank investment (MII, Malaysia’s IIMM)","topicId":"t8.8.5","conceptId":"liquidity","productIds":["interbank-mudarabah"],"summary":"A surplus bank invests with a deficit bank on Mudarabah for overnight to 12 months; the return is a negotiated share of the investee’s actual profit rate, known only at the end.","parties":[{"id":"investor","label":"Surplus (investor) bank","x":14,"y":30},{"id":"investee","label":"Deficit (investee) bank","x":86,"y":30},{"id":"bnm","label":"Central bank (BNM)","x":50,"y":4}],"steps":[{"from":"bnm","to":"investee","kind":"contract","label":"Minimum benchmark rate","detail":"From February 1996: government investment issue rate + 0.5 %, so only banks with reasonable returns take funds (p. 206)."},{"from":"investor","to":"investee","kind":"contract","label":"Profit-sharing ratio negotiated","detail":"Tenor from overnight to 12 months."},{"from":"investor","to":"investee","kind":"cash","label":"Principal placed","detail":"The investee uses it in its Shari’ah-compliant business."},{"from":"investee","to":"investor","kind":"risk","label":"Return not known in advance","detail":"Based on the investee’s gross profit rate before distribution on one-year investments."},{"from":"investee","to":"investor","kind":"cash","label":"Principal + share of profit at maturity","detail":"The actual return crystallises at the end of the period."}],"rules":["No fixed return: the ratio is agreed, and the rate is known only at the end.","The benchmark filters participants; it is not a guarantee."],"pitfalls":["Treating the placement as a fixed-rate deposit","Promising the benchmark as the return"],"origin":["f1"]},{"id":"dm-construction","title":"House on the customer’s land: sale and lease-back Diminishing Musharakah (Box 12.4)","topicId":"t12.9.2","conceptId":"diminishing-musharakah","modeId":"diminishing-musharakah","productIds":["house-construction-dm"],"summary":"The bank buys part of the client’s land to become co-owner, releases the price in instalments to build the house, then leases its share and sells it back unit by unit.","parties":[{"id":"client","label":"Client (owns the land)","x":14,"y":30},{"id":"bank","label":"Islamic bank","x":86,"y":30},{"id":"house","label":"Joint property","x":50,"y":56}],"steps":[{"from":"client","to":"bank","kind":"ownership","label":"Bank buys 8 of 10 land units","detail":"Land worth Drs 1,000,000; the bank buys Drs 800,000 of it (Shirkatulmilk)."},{"from":"bank","to":"client","kind":"cash","label":"Price paid in four instalments","detail":"Drs 200,000 each; the client uses them to build the house."},{"from":"client","to":"house","kind":"goods","label":"House built on the joint land","detail":"The client supervises the construction."},{"from":"bank","to":"client","kind":"rent","label":"Lease of the bank’s share","detail":"Starts when the house is habitable; for the first year only rent is paid, so it does not fall."},{"from":"client","to":"bank","kind":"cash","label":"Unit purchases begin a year after the last instalment","detail":"The gap avoids buy-back (‘Inah); rent falls with each unit bought."},{"from":"bank","to":"client","kind":"ownership","label":"Title passes after the last unit","detail":"For a renovation, rent starts from the first month because the client already lives in the house."}],"rules":["One-year gap before units are sold back (p. 341).","No rent until the house can be used (except in a renovation)."],"pitfalls":["Selling units back immediately (‘Inah)","Charging rent during construction"],"origin":["f1"]},{"id":"post-shipment","title":"Post-shipment finance: Qard against the export bill plus a collection fee","topicId":"t14.4.2","conceptId":"qard","modeId":"qard-hasan","productIds":["post-shipment-qard"],"summary":"Instead of discounting, the bank lends the bill amount interest-free, collects the bill as the exporter’s agent for a flat fee, and may earn the exchange differential through a promise.","parties":[{"id":"exporter","label":"Exporter","x":14,"y":30},{"id":"bank","label":"Islamic bank","x":50,"y":6},{"id":"importer","label":"Importer’s bank","x":86,"y":30}],"steps":[{"from":"exporter","to":"bank","kind":"contract","label":"Bill lodged for collection","detail":"The bank acts as collecting agent (Wakalah)."},{"from":"bank","to":"exporter","kind":"cash","label":"Qard at face value, at spot rate","detail":"No deduction that grows with time (p. 371)."},{"from":"exporter","to":"bank","kind":"promise","label":"Promise to sell the FX proceeds","detail":"Exchange at settlement; the rate differential is the bank’s income (Box 8.2)."},{"from":"importer","to":"bank","kind":"cash","label":"Bill paid at maturity","detail":"Proceeds repay the Qard."},{"from":"exporter","to":"bank","kind":"cash","label":"Flat collection fee","detail":"Related to the amount, not to the days outstanding."}],"rules":["Face value; no time-based charge on the loan.","The FX leg is a promise; the actual exchange is spot at settlement."],"pitfalls":["A fee that rises with the number of days","Buying the bill at a discount"],"origin":["f1"]},{"id":"islamic-fund","title":"Islamic equity fund: screening and purification","topicId":"t8.8.1","conceptId":"screening","productIds":["equity-fund"],"summary":"Investors pool money with a manager who invests only in screened shares, purifies tainted income and distributes actual gains pro rata.","parties":[{"id":"investors","label":"Unit holders","x":12,"y":30},{"id":"manager","label":"Fund manager","x":50,"y":30},{"id":"stocks","label":"Screened companies","x":88,"y":30},{"id":"charity","label":"Charity account","x":50,"y":58}],"steps":[{"from":"investors","to":"manager","kind":"cash","label":"Subscriptions","detail":"No guarantee of principal or of a rate of profit (p. 202)."},{"from":"manager","to":"stocks","kind":"contract","label":"Screen before buying","detail":"Halal business; debt, cash and receivables each < 33 % of average market cap (DJIM)."},{"from":"manager","to":"stocks","kind":"cash","label":"Shares bought","detail":"Regular income, capital gain, aggressive or balanced strategy."},{"from":"stocks","to":"manager","kind":"cash","label":"Dividends and capital gains","detail":"Returns as actually earned."},{"from":"manager","to":"charity","kind":"cash","label":"Purification","detail":"Charity rate (non-compliant income ÷ gross revenue) × dividend (Al Meezan method)."},{"from":"manager","to":"investors","kind":"cash","label":"Net returns pro rata","detail":"The manager takes a profit share (Mudarabah) or a fee on NAV (agency)."}],"rules":["Screen and re-screen; divest stocks that fail.","Purify income; the manager is not obliged to purify its own fee."],"pitfalls":["Promising a fixed return","Keeping non-compliant income"],"origin":["f1"]},{"id":"salam-sukuk","title":"Salam Sukuk: Bahrain’s aluminium securities (BMA, 2001)","topicId":"t15.3.5.c","conceptId":"salam","modeId":"salam","productIds":["salam-sukuk"],"summary":"Banks pay the government in advance for aluminium to be delivered in three months, then appoint the government to sell it on their behalf.","parties":[{"id":"banks","label":"Participating banks (Sukuk holders)","x":12,"y":30},{"id":"bib","label":"Bahrain Islamic Bank (representative)","x":50,"y":6},{"id":"gov","label":"Government of Bahrain","x":88,"y":30},{"id":"market","label":"Aluminium buyers","x":50,"y":58}],"steps":[{"from":"banks","to":"bib","kind":"cash","label":"Subscriptions","detail":"Three-month Salam securities held for liquidity requirements."},{"from":"bib","to":"gov","kind":"cash","label":"Salam price paid in advance","detail":"For a specified amount of aluminium at a future date."},{"from":"bib","to":"gov","kind":"agency","label":"Government appointed selling agent","detail":"A separate agency contract."},{"from":"gov","to":"market","kind":"goods","label":"Aluminium delivered and sold","detail":"At a price that gives holders their return."},{"from":"gov","to":"banks","kind":"cash","label":"Sale proceeds to holders","detail":"Certificates are not traded before delivery: they are a Salam debt (p. 404)."}],"rules":["Full advance payment; a precisely specified commodity.","No secondary trading of Salam debt."],"pitfalls":["Trading the certificates before delivery","Guaranteeing the sale price"],"origin":["f1"]},{"id":"idb-sukuk","title":"Mixed-portfolio Sukuk: IDB Solidarity Trust (2003, Figure 15.2)","topicId":"t15.3.5.d","conceptId":"sukuk","modeId":"sukuk","productIds":["mixed-portfolio-sukuk"],"summary":"IDB’s Ijarah, Murabaha and Istisna‘a assets pass through ICD to a trust SPV that issues US$400 m certificates; Ijarah must stay above 50 % of the pool.","parties":[{"id":"idb","label":"IDB (originator, guarantor)","x":12,"y":30},{"id":"icd","label":"ICD (buyer, then Wakil)","x":50,"y":4},{"id":"spv","label":"Trust SPV","x":88,"y":30},{"id":"investors","label":"Certificate holders","x":50,"y":58}],"steps":[{"from":"idb","to":"icd","kind":"ownership","label":"Portfolio sold to ICD","detail":"Ijarah, Murabaha and Istisna‘a contracts."},{"from":"icd","to":"spv","kind":"ownership","label":"ICD sells the assets to the SPV","detail":"The SPV then appoints ICD its Wakil to manage them."},{"from":"investors","to":"spv","kind":"cash","label":"US$400 m subscribed","detail":"Each certificate is an undivided beneficial ownership, pari passu."},{"from":"spv","to":"investors","kind":"cash","label":"Periodic distributions","detail":"From the assets’ profit, net of trust expenses."},{"from":"idb","to":"spv","kind":"promise","label":"Guarantee and purchase undertaking","detail":"Guarantees obligors’ scheduled payments; buys the assets at maturity or if Ijarah falls below 25 %."}],"rules":["Over 50 % Ijarah at all times keeps the certificates tradable.","Principal is reinvested in Ijarah and Musharakah."],"pitfalls":["Letting receivables dominate the pool","Reading the guarantee as a guarantee of the certificates themselves"],"origin":["f1"]}]);
